/*
 * A106728  Triangle T(n, k) = ( ((f(n+1) mod 5) mod 4) + ((f(k+1) mod 5) mod
 *          4) ) mod 4, where f(n) = 10 - (prime(n+3) mod 10).
 * https://oeis.org/A106728
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl, easy, less
 * Formula:   a(n) = T(row(n), col(n)) with T(n,k) = ((f(n+1) mod 5) mod 4 +
 *            (f(k+1) mod 5) mod 4) mod 4, and f(m) = 10 - (prime(m+3) mod
 *            10). Here prime(i) denotes the i‑th prime (prime(1)=2). The
 *            flattened triangle is generated by row-major order: row r has
 *            indices r(r+1)/2 … r(r+1)/2 + r. The function compu...
 * Range:     u8 n <= 1325, u16 n <= 1325, u32 n <= 1325, u64 n <= 1325,
 *            u128 n <= 1325, big any n
 * Validated: standard, pass, 121 terms through n = 1235 (2026-11-01)
 * Helpers:   is_prime_trial
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/is_prime_trial.h"

/*--- dynamic array helpers for primes --------------------------------------*/
static void ensure_primes_cap(size_t *cap, uint64_t **arr, size_t min_cap) {
    if (*cap < min_cap) {
        size_t new_cap = (*cap) ? (*cap) << 1 : 16;
        if (new_cap < min_cap) new_cap = min_cap;
        uint64_t *tmp = (uint64_t *)realloc(*arr, new_cap * sizeof(uint64_t));
        if (!tmp) abort();
        *arr = tmp;
        *cap = new_cap;
    }
}

static seq_t get_prime(uint64_t idx) {
    static uint64_t *prime_vec = NULL;
    static size_t prime_cap = 0;
    static size_t prime_sz  = 0;
    static uint64_t candidate = 3;      /* next odd to test */

    if (!prime_vec) { /* first call: initialise */
        ensure_primes_cap(&prime_cap, &prime_vec, 16);
        prime_vec[0] = 2;
        prime_sz = 1;
    }

    while (prime_sz < idx) {
        /* find next prime */
        while (!is_prime_trial(candidate, prime_vec, prime_sz))
            candidate += 2;

        /* add found prime */
        if (prime_sz == prime_cap)
            ensure_primes_cap(&prime_cap, &prime_vec, prime_cap << 1);

        prime_vec[prime_sz++] = candidate;
        candidate += 2;
    }
    return (seq_t)prime_vec[idx - 1];
}

static inline idx_t
row_of(idx_t n)                 /* return r with r(r+1)/2 ≤ n < (r+1)(r+2)/2 */
{
    idx_t low  = 0;
    idx_t high = 1;
    /* exponential search to find an upper bound */
    while ((unsigned __int128)high * (high + 1) / 2 <= n) {
        low  = high;
        high <<= 1;              /* double high */
    }
    /* binary search between low (inclusive) and high (inclusive) */
    while (low < high) {
        idx_t mid = low + ((high - low) >> 1) + 1; /* upper mid to avoid infinite loop */
        if ((unsigned __int128)mid * (mid + 1) / 2 <= n)
            low = mid;
        else
            high = mid - 1;
    }
    return low;
}

seq_t a(idx_t n)
{
    /* Determine row r and column c of the n‑th element. */
    idx_t r = row_of(n);                     /* r(r+1)/2 ≤ n < (r+1)(r+2)/2 */
    idx_t c = n - r * (r + 1) / 2;            /* column within the row */

    /* Prime numbers needed: prime(r+4) and prime(c+4).  */
    seq_t p_r = get_prime(r + 4);              /* prime(r+1+3)  */
    seq_t p_c = get_prime(c + 4);              /* prime(c+1+3)  */

    /* Compute the function f for both indices. */
    seq_t f_r = (seq_t)10 - (p_r % (seq_t)10);
    seq_t f_c = (seq_t)10 - (p_c % (seq_t)10);

    /* ((f mod 5) mod 4) for each side. */
    seq_t val_r = (f_r % (seq_t)5) % (seq_t)4;
    seq_t val_c = (f_c % (seq_t)5) % (seq_t)4;

    /* Final triangle entry. */
    return (val_r + val_c) % (seq_t)4;
}
